// Class 11 Physics Unit I: Physical World and Measurement (Units and Measurements)
// High-Level Reference Book Content & NCERT Solutions

export const c11Phy1HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Fundamental Terms & Concepts for Unit I: Physical World and Measurement (Units and Measurements)</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>1. Physical Quantity:</b>\n        <span style=\"color: #FFFFFF;\">Any property of a material or system that can be quantified and measured using an accepted standard.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>2. Unit of Measurement:</b>\n        <span style=\"color: #FFFFFF;\">An arbitrarily chosen, internationally accepted standard reference quantity used to compare physical measurements.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>3. Fundamental Quantities:</b>\n        <span style=\"color: #FFFFFF;\">Base physical quantities that are independent of each other and cannot be defined in terms of other quantities (e.g. Mass, Length, Time).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>4. Derived Quantities:</b>\n        <span style=\"color: #FFFFFF;\">Quantities that can be expressed as mathematical combinations of fundamental base quantities (e.g. Velocity, Force, Work).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>5. SI Units:</b>\n        <span style=\"color: #FFFFFF;\">Le Système International d'Unités - the modern metric standard system based on 7 base and 2 supplementary units.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>6. Significant Figures:</b>\n        <span style=\"color: #FFFFFF;\">The total number of reliable digits in a measured quantity plus the first single digit that is uncertain.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>7. Dimensions:</b>\n        <span style=\"color: #FFFFFF;\">The powers (exponents) to which fundamental units are raised to represent a physical quantity.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>8. Dimensional Formula:</b>\n        <span style=\"color: #FFFFFF;\">An expression showing which base quantities and what powers enter into the unit of a physical quantity (e.g. Force = [M L T<sup>-2</sup>]).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>9. Principle of Homogeneity:</b>\n        <span style=\"color: #FFFFFF;\">The fundamental principle stating that dimensions of all terms on both sides of a valid physical equation must be identical.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>10. Systematic Error:</b>\n        <span style=\"color: #FFFFFF;\">Errors that tend to occur in one direction only (either positive or negative) due to instrument flaws or technique.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: NEED FOR MEASUREMENT -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 25px;\">Need for Measurement</h2>\n  \n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Measurement):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Measurement is the process of comparing an unknown physical quantity with a standard reference magnitude of the exact same physical kind to determine how many times the standard is contained within it.</p>\n  </div>\n\n  <p>Physics is an exact quantitative science based on observation, experimentation, and accurate numerical measurement. Qualitative descriptions such as 'hot', 'heavy', or 'fast' are subjective and insufficient for scientific analysis. To establish exact quantitative laws of nature, physical quantities must be measured accurately using well-defined standards.</p>\n  \n  <p>Every physical measurement consists of two essential parts: a numerical value (magnitude <i>n</i>) and a unit of measurement (<i>u</i>). The physical quantity <i>Q</i> is mathematically represented as:</p>\n  \n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Q = n × u</b></div>\n\n  <p>If a physical quantity is measured in two different unit systems with units <i>u</i><sub>1</sub> and <i>u</i><sub>2</sub> having numerical values <i>n</i><sub>1</sub> and <i>n</i><sub>2</sub> respectively, the total magnitude remains unchanged:</p>\n  \n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>n<sub>1</sub> u<sub>1</sub> = n<sub>2</sub> u<sub>2</sub> &nbsp; ⇒ &nbsp; n ∝ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">u</span>\n  </span></b></div>\n\n  <p>This fundamental inverse relationship implies that the larger the unit chosen for measurement, the smaller will be the numerical value obtained for the given quantity.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Role of Measurement in Physical Sciences</h3>\n  <p>Accurate measurement enables physicists to test theoretical predictions against experimental data. From describing subatomic particle trajectories to calculating planetary orbits across light years, measurement bridges theoretical models with real-world physical reality.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Characteristics of a Standard Unit</h3>\n  <p>To serve as a reliable reference standard, a unit of measurement must possess the following essential characteristics:</p>\n  \n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Well-Defined:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">The definition of the unit must be clear, precise, and completely unambiguous.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Invariable:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">The standard unit must not change with environmental factors like temperature, pressure, or location.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Easily Reproducible:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">It should be possible to replicate the standard unit with high precision anywhere in the world.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Universally Accepted:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">It must be internationally agreed upon by the global scientific community.</span>\n  </div>\n  </div>\n\n  \n  <div style=\"border: 2px dashed #FF512F; border-radius: 12px; padding: 18px; text-align: center; margin: 20px 0; background: rgba(255, 81, 47, 0.04);\">\n    <div style=\"font-size: 22px; margin-bottom: 4px;\">🖼️</div>\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">[ Diagram Placeholder: Comparison of Measurement Process & Unit Standard ]</div>\n    <div style=\"color: #B0BEC5; font-size: 13.5px; max-width: 600px; margin: 0 auto; line-height: 1.4;\">Schematic diagram showing an unknown physical quantity being measured against a calibrated standard unit scale Q = n × u.</div>\n  </div>\n\n  <!-- SECTION 2: UNITS OF MEASUREMENT & SYSTEMS OF UNITS -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">Units of Measurement & Systems of Units</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (System of Units):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A complete set of units containing both fundamental base units and derived units used to measure all types of physical quantities in a given scientific framework.</p>\n  </div>\n\n  <p>Historically, different countries and regions developed independent systems of units based on local conventions for length, mass, and time. Before the global adoption of the metric system, three major unit systems were widely employed in science and engineering:</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) CGS System (Gaussian System)</h3>\n  <p>Originating in France, the CGS system is a metric system based on three fundamental units:</p>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Length:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Centimetre (cm)</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Mass:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Gram (g)</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Time:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Second (s)</span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) FPS System (British Engineering System)</h3>\n  <p>The FPS system is a non-metric imperial system based on:</p>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Length:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Foot (ft)</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Mass:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Pound (lb)</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Time:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Second (s)</span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iii) MKS System</h3>\n  <p>The MKS system is a coherent metric system based on larger practical units:</p>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Length:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Metre (m)</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Mass:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Kilogram (kg)</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Time:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Second (s)</span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iv) Need for a Universal System</h3>\n  <p>As international scientific collaboration and commerce expanded in the 20th century, converting between disparate systems like FPS and CGS caused severe confusion and errors. This highlighted the urgent necessity for a unified, coherent global standard system of units.</p>\n\n  \n  <div style=\"border: 2px dashed #FF512F; border-radius: 12px; padding: 18px; text-align: center; margin: 20px 0; background: rgba(255, 81, 47, 0.04);\">\n    <div style=\"font-size: 22px; margin-bottom: 4px;\">🖼️</div>\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">[ Diagram Placeholder: Comparison Table of CGS, FPS, MKS and SI Systems ]</div>\n    <div style=\"color: #B0BEC5; font-size: 13.5px; max-width: 600px; margin: 0 auto; line-height: 1.4;\">Comparative chart displaying the base dimensions of Length, Mass, and Time across CGS, FPS, MKS, and SI unit systems.</div>\n  </div>\n\n  <!-- SECTION 3: SI UNITS: FUNDAMENTAL AND DERIVED UNITS -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">SI Units: Fundamental and Derived Units</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (SI System (Système International d'Unités)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The modern international metric standard system established in 1960 by the General Conference on Weights and Measures (CGPM), built upon 7 fundamental base units and 2 supplementary units.</p>\n  </div>\n\n  <p>The International System of Units (SI) is a <b>coherent system of units</b>, meaning that derived units are obtained directly by simple multiplication or division of base units without introducing numerical conversion factors.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) The 7 SI Base Fundamental Quantities & Units</h3>\n  <p>All physical quantities in the universe can be expressed in terms of 7 independent fundamental base quantities:</p>\n\n  <!-- TABLE WITH CLEAN INLINE SLASHES FOR CELL VISIBILITY -->\n  <div style=\"overflow-x: auto; margin: 15px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; background: rgba(0,0,0,0.25); text-align: left; font-size: 13.5px;\">\n      <thead>\n        <tr style=\"background: rgba(255, 81, 47, 0.2); color: #FF512F; border-bottom: 2px solid #FF512F;\">\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Base Quantity</th>\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">SI Unit</th>\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Symbol</th>\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Definition Basis</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Length</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">metre</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>m</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Path length traveled by light in vacuum in 1 / 299,792,458 s.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Mass</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">kilogram</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>kg</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Defined by fixing Planck's constant h = 6.62607015 × 10<sup>-34</sup> J s.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Time</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">second</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>s</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Duration of 9,192,631,770 periods of Cs-133 radiation.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Electric Current</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">ampere</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>A</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Defined by elementary charge e = 1.602176634 × 10<sup>-19</sup> C.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Thermodynamic Temp.</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">kelvin</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>K</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Defined by Boltzmann constant k = 1.380649 × 10<sup>-23</sup> J K<sup>-1</sup>.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Amount of Substance</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">mole</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>mol</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Contains exactly 6.02214076 × 10<sup>23</sup> entities (Avogadro constant).</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Luminous Intensity</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">candela</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>cd</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Intensity of 540 × 10<sup>12</sup> Hz source emitting 1/683 W sr<sup>-1</sup>.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Supplementary SI Units</h3>\n  <p>In addition to 7 base units, SI includes two supplementary dimensionless geometrical units:</p>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Plane Angle (dθ):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Measured in <b>radian (rad)</b>. Defined as arc length divided by radius: <code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">dθ = ds / r</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Solid Angle (dΩ):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Measured in <b>steradian (sr)</b>. Defined as intercepted area divided by radius squared: <code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">dΩ = dA / r<sup>2</sup></code></span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iii) Derived Units</h3>\n  <p>Derived units are mathematical combinations of fundamental units. Examples include:</p>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Speed / Velocity:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">unit = m / s = m s<sup>-1</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Acceleration:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">unit = m / s<sup>2</sup> = m s<sup>-2</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Force:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">1 Newton (N) = 1 kg m s<sup>-2</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Pressure:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">1 Pascal (Pa) = 1 N / m<sup>2</sup> = 1 kg m<sup>-1</sup> s<sup>-2</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Work / Energy:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">1 Joule (J) = 1 N m = 1 kg m<sup>2</sup> s<sup>-2</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Power:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">1 Watt (W) = 1 J / s = 1 kg m<sup>2</sup> s<sup>-3</sup></code></span>\n  </div>\n  </div>\n\n  \n  <div style=\"border: 2px dashed #FF512F; border-radius: 12px; padding: 18px; text-align: center; margin: 20px 0; background: rgba(255, 81, 47, 0.04);\">\n    <div style=\"font-size: 22px; margin-bottom: 4px;\">🖼️</div>\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">[ Diagram Placeholder: 7 SI Base Units and 2 Supplementary Geometrical Units Chart ]</div>\n    <div style=\"color: #B0BEC5; font-size: 13.5px; max-width: 600px; margin: 0 auto; line-height: 1.4;\">Visual flowchart showing how 7 Base SI Units combine to form Derived Units like Force, Pressure, Energy, and Power.</div>\n  </div>\n\n  <!-- SECTION 4: SIGNIFICANT FIGURES & ERROR ANALYSIS -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">Significant Figures & Error Analysis</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Significant Figures):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The total number of reliable digits in a measured quantity plus the first single uncertain digit that carries experimental ambiguity.</p>\n  </div>\n\n  <p>Every experimental measurement contains an intrinsic degree of uncertainty depending on the precision of the measuring instrument. Significant figures indicate the precision of a measurement.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Rules for Determining Significant Figures</h3>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Rule 1: All Non-Zero Digits:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">All non-zero digits are significant (e.g. 143.85 has 5 significant figures).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Rule 2: Trapped Zeros:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">All zeros occurring between two non-zero digits are significant (e.g. 2008.05 has 6 significant figures).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Rule 3: Leading Zeros:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Leading zeros to the left of the first non-zero digit are NEVER significant (e.g. 0.0042 has only 2 significant figures).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Rule 4: Trailing Zeros with Decimal:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Trailing zeros in a number with a decimal point ARE significant (e.g. 3.500 has 4 significant figures).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Rule 5: Whole Number Trailing Zeros:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Trailing zeros in a whole number without a decimal point are ambiguous; use scientific notation N × 10<sup>x</sup> (e.g. 4.70 × 10<sup>3</sup> has 3 significant figures).</span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Rounding Off Numbers & Arithmetic Operations</h3>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Addition & Subtraction Rule:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">The final calculated result should retain only as many decimal places as present in the measurement having the least number of decimal places.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Multiplication & Division Rule:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">The final calculated result should retain only as many significant figures as present in the original number with the least significant figures.</span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iii) Error Analysis & Types of Errors</h3>\n  <p>The difference between the true value and the measured value of a physical quantity is called an <b>experimental error</b>.</p>\n\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Absolute Error (Δa<sub>i</sub>):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Magnitude of difference between true value a<sub>m</sub> and individual measured value a<sub>i</sub>:<br><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">Δa<sub>i</sub> = |a<sub>m</sub> - a<sub>i</sub>|</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Mean Absolute Error (Δa<sub>mean</sub>):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Arithmetic mean of absolute errors of all individual measurements.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Relative Error:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Ratio of mean absolute error to mean value:<br><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">Relative Error = Δa<sub>mean</sub> / a<sub>mean</sub></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Percentage Error:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Relative error expressed in percent:<br><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">Percentage Error = (Δa<sub>mean</sub> / a<sub>mean</sub>) × 100%</code></span>\n  </div>\n  </div>\n\n  <!-- CLEAN STRUCTURED BREAKDOWN FOR COMBINATION OF ERRORS (REQUESTED BY USER) -->\n  <h3 style=\"color: #FF512F; margin-top: 22px;\">Combination of Errors</h3>\n\n  <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #FF512F; border-radius: 8px; padding: 14px; margin: 12px 0;\">\n    <div style=\"color: #FFFFFF; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">• If Z = A + B &nbsp;or&nbsp; Z = A - B:</div>\n    <b style=\"color: #FF512F; display: block; font-size: 15px; margin-bottom: 4px;\">Maximum Absolute Error:</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; font-weight: bold; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px; display: inline-block; white-space: nowrap;\">ΔZ = ΔA + ΔB</div>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #FF512F; border-radius: 8px; padding: 14px; margin: 12px 0;\">\n    <div style=\"color: #FFFFFF; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">• If Z = A × B &nbsp;or&nbsp; Z = A / B:</div>\n    <b style=\"color: #FF512F; display: block; font-size: 15px; margin-bottom: 4px;\">Maximum Relative Error:</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; font-weight: bold; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px; display: inline-block; white-space: nowrap;\"><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔZ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Z</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔB</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">B</span>\n  </span></div>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #FF512F; border-radius: 8px; padding: 14px; margin: 12px 0;\">\n    <div style=\"color: #FFFFFF; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">• If Z = A<sup>p</sup> B<sup>q</sup> / C<sup>r</sup>:</div>\n    <b style=\"color: #FF512F; display: block; font-size: 15px; margin-bottom: 4px;\">Maximum Fractional Error:</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; font-weight: bold; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px; display: inline-block; white-space: nowrap;\"><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔZ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Z</span>\n  </span> = p <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span> + q <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔB</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">B</span>\n  </span> + r <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔC</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">C</span>\n  </span></div>\n  </div>\n\n  \n  <div style=\"border: 2px dashed #FF512F; border-radius: 12px; padding: 18px; text-align: center; margin: 20px 0; background: rgba(255, 81, 47, 0.04);\">\n    <div style=\"font-size: 22px; margin-bottom: 4px;\">🖼️</div>\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">[ Diagram Placeholder: Significant Figures Rules & Error Propagation Tree ]</div>\n    <div style=\"color: #B0BEC5; font-size: 13.5px; max-width: 600px; margin: 0 auto; line-height: 1.4;\">Diagram depicting rules for counting significant figures and step-by-step formula tree for combining absolute and percentage errors.</div>\n  </div>\n\n  <!-- SECTION 5: DIMENSIONS OF PHYSICAL QUANTITIES -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">Dimensions of Physical Quantities</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Dimensions):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The powers or exponents to which fundamental base quantities (Mass [M], Length [L], Time [T], Current [I], Temp [K]) are raised to represent a given physical quantity.</p>\n  </div>\n\n  <p>In mechanics, all physical quantities can be represented dimensionally in terms of three fundamental base dimensions: Mass <b>[M]</b>, Length <b>[L]</b>, and Time <b>[T]</b>. In thermodynamics and electromagnetism, Temperature <b>[K]</b> and Electric Current <b>[A]</b> are added.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Dimensional Formula & Dimensional Equation</h3>\n  <p>An expression showing how and which fundamental quantities enter into a physical quantity is called its <b>dimensional formula</b>. When a physical quantity is equated with its dimensional formula, it is called a <b>dimensional equation</b>.</p>\n\n  <!-- TABLE WITH CLEAN INLINE SLASHES FOR CELL VISIBILITY -->\n  <div style=\"overflow-x: auto; margin: 15px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; background: rgba(0,0,0,0.25); text-align: left; font-size: 13.5px;\">\n      <thead>\n        <tr style=\"background: rgba(255, 81, 47, 0.2); color: #FF512F; border-bottom: 2px solid #FF512F;\">\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Physical Quantity</th>\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Defining Relation</th>\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Dimensional Formula</th>\n          <th style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">SI Unit</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Area</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Length × Breadth</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>0</sup> L<sup>2</sup> T<sup>0</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">m<sup>2</sup></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Volume</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Length × Breadth × Height</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>0</sup> L<sup>3</sup> T<sup>0</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">m<sup>3</sup></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Density</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Mass / Volume</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>1</sup> L<sup>-3</sup> T<sup>0</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">kg m<sup>-3</sup></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Velocity / Speed</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Displacement / Time</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>0</sup> L<sup>1</sup> T<sup>-1</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">m s<sup>-1</sup></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Acceleration</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Velocity Change / Time</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>0</sup> L<sup>1</sup> T<sup>-2</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">m s<sup>-2</sup></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Linear Momentum</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Mass × Velocity</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>1</sup> L<sup>1</sup> T<sup>-1</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">kg m s<sup>-1</sup></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Force</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Mass × Acceleration</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>1</sup> L<sup>1</sup> T<sup>-2</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">N (kg m s<sup>-2</sup>)</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Work / Energy</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Force × Distance</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>1</sup> L<sup>2</sup> T<sup>-2</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">J (kg m<sup>2</sup> s<sup>-2</sup>)</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Power</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Work / Time</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">W (J s<sup>-1</sup>)</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Pressure / Stress</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Force / Area</td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</b></td>\n          <td style=\"padding: 6px 8px; border: 1px solid rgba(255,255,255,0.1);\">Pa (N m<sup>-2</sup>)</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Classification of Physical Quantities</h3>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Dimensional Variables:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Quantities possessing dimensions and variable values (e.g. Velocity, Force).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Dimensional Constants:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Quantities possessing dimensions but constant fixed values (e.g. Gravitational Constant G = [M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>], Planck's Constant h = [M L<sup>2</sup> T<sup>-1</sup>]).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Dimensionless Variables:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Quantities having variable values but zero dimensions [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>] (e.g. Strain, Angle, Relative Density, Refractive Index).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Dimensionless Constants:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Pure numbers having constant values and zero dimensions (e.g. π, e, 1, 2, 3).</span>\n  </div>\n  </div>\n\n  \n  <div style=\"border: 2px dashed #FF512F; border-radius: 12px; padding: 18px; text-align: center; margin: 20px 0; background: rgba(255, 81, 47, 0.04);\">\n    <div style=\"font-size: 22px; margin-bottom: 4px;\">🖼️</div>\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">[ Diagram Placeholder: Classification Matrix of Physical Quantities by Dimensions ]</div>\n    <div style=\"color: #B0BEC5; font-size: 13.5px; max-width: 600px; margin: 0 auto; line-height: 1.4;\">2x2 grid diagram showing Dimensional Variables, Dimensional Constants, Dimensionless Variables, and Dimensionless Constants with clear examples.</div>\n  </div>\n\n  <!-- SECTION 6: DIMENSIONAL ANALYSIS AND ITS APPLICATIONS -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">Dimensional Analysis and Its Applications</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Principle of Homogeneity of Dimensions):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The fundamental law stating that a physical equation is dimensionally correct if and only if the dimensions of every term on the left-hand side (LHS) are identical to the dimensions of every term on the right-hand side (RHS).</p>\n  </div>\n\n  <p>Dimensional analysis is a powerful analytical technique used in physics to inspect physical relations, derive empirical formulas, and convert numerical values between different unit systems.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Principle of Homogeneity of Dimensions</h3>\n  <p>Only physical quantities having identical dimensions can be added, subtracted, or equated. For an equation <code>A + B = C</code>, the dimensions of A, B, and C must be strictly identical:</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>[A] = [B] = [C]</b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Application 1: Checking the Dimensional Correctness of an Equation</h3>\n  <p>To verify a physical equation, compare the dimensional formulas of LHS and RHS.</p>\n  <p><b>Example:</b> Check correctness of equation of motion <code>s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup></code>.</p>\n\n  <!-- EACH STEP ON A CLEAN NEW LINE WITH NOWRAP MATH STATEMENTS -->\n  <div style=\"background: rgba(0,0,0,0.25); border: 1px solid rgba(255, 81, 47, 0.25); border-radius: 8px; padding: 12px 16px; margin: 12px 0; font-size: 14.5px;\">\n    <div style=\"margin-bottom: 8px; color: #FF512F; font-weight: bold; white-space: nowrap; overflow-x: auto;\">• LHS: [s] = [L]</div>\n    <div style=\"margin-bottom: 8px; color: #FFFFFF; font-weight: bold; white-space: nowrap; overflow-x: auto;\">• RHS Term 1: [u t] = [L T<sup>-1</sup>] × [T] = [L]</div>\n    <div style=\"color: #FFFFFF; font-weight: bold; white-space: nowrap; overflow-x: auto;\">• RHS Term 2: [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup>] = [1] × [L T<sup>-2</sup>] × [T<sup>2</sup>] = [L] <span style=\"color: #B0BEC5; font-weight: normal;\">(Pure number <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> is dimensionless)</span></div>\n  </div>\n\n  <p>Since LHS = RHS = [L], the equation is dimensionally homogeneous and correct!</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iii) Application 2: Deriving Relationships Between Physical Quantities</h3>\n  <p>If a physical quantity depends on other factors, its functional dependence can be derived by equating dimensions.</p>\n  <p><b>Example:</b> Derive period of simple pendulum T depending on mass m, length l, and acceleration due to gravity g.</p>\n  <p>Assume <code>T = k m<sup>a</sup> l<sup>b</sup> g<sup>c</sup></code> where k is dimensionless constant.</p>\n  <p>Substitute dimensions: <code>[M<sup>0</sup> L<sup>0</sup> T<sup>1</sup>] = [M]<sup>a</sup> [L]<sup>b</sup> [L T<sup>-2</sup>]<sup>c</sup> = [M<sup>a</sup> L<sup>b+c</sup> T<sup>-2c</sup>]</code></p>\n\n  <div style=\"background: rgba(0,0,0,0.25); border: 1px solid rgba(255, 81, 47, 0.25); border-radius: 8px; padding: 12px 16px; margin: 12px 0; font-size: 14.5px;\">\n    <div style=\"margin-bottom: 6px; color: #FFFFFF; white-space: nowrap;\">• Power of M: <b>a = 0</b></div>\n    <div style=\"margin-bottom: 6px; color: #FFFFFF; white-space: nowrap;\">• Power of T: <b>-2c = 1 &nbsp; ⇒ &nbsp; c = -<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span></b></div>\n    <div style=\"color: #FFFFFF; white-space: nowrap;\">• Power of L: <b>b + c = 0 &nbsp; ⇒ &nbsp; b = -c = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span></b></div>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>T = k m<sup>0</sup> l<sup>1/2</sup> g<sup>-1/2</sup> = k <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span> = 2 π <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span></b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iv) Application 3: Conversion of Units from One System to Another</h3>\n  <p>Based on <code>n<sub>1</sub> u<sub>1</sub> = n<sub>2</sub> u<sub>2</sub></code>:</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>n<sub>2</sub> = n<sub>1</sub> × [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">M<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M<sub>2</sub></span>\n  </span> ]<sup>a</sup> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L<sub>2</sub></span>\n  </span> ]<sup>b</sup> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sub>2</sub></span>\n  </span> ]<sup>c</sup></b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(v) Limitations of Dimensional Analysis</h3>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Limitation 1: Constant Identification:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">It cannot determine the value of dimensionless proportional constants (like 2π, 1/2).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Limitation 2: Variable Count Boundary:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">It fails if a physical quantity depends on more than 3 fundamental base quantities in mechanics.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Limitation 3: Non-Algebraic Functions:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">It cannot derive formulas containing trigonometric (sin, cos), exponential (e<sup>x</sup>), or logarithmic (log x) functions.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Limitation 4: Scalar/Vector Ambiguity:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">It cannot distinguish whether a physical quantity is a scalar or a vector.</span>\n  </div>\n  </div>\n\n  \n  <div style=\"border: 2px dashed #FF512F; border-radius: 12px; padding: 18px; text-align: center; margin: 20px 0; background: rgba(255, 81, 47, 0.04);\">\n    <div style=\"font-size: 22px; margin-bottom: 4px;\">🖼️</div>\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 15.5px; margin-bottom: 4px;\">[ Diagram Placeholder: 3 Applications & Limitations of Dimensional Analysis Flowchart ]</div>\n    <div style=\"color: #B0BEC5; font-size: 13.5px; max-width: 600px; margin: 0 auto; line-height: 1.4;\">Flowchart detailing the 3 core applications of dimensional analysis and its 4 fundamental limitations.</div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET (PLACED AT THE END OF OVERVIEW SECTION) -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 16px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Formulae, Astronomical Conversions & Fast Rules Summary for Chapter 1</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Measurement Relation:</b>\n        <span style=\"color: #FFFFFF; white-space: nowrap; display: block; overflow-x: auto;\">Q = n × u &nbsp;|&nbsp; n<sub>1</sub> u<sub>1</sub> = n<sub>2</sub> u<sub>2</sub> &nbsp;|&nbsp; n ∝ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">u</span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Astronomical Distance Units:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">1 AU = 1.496 × 10<sup>11</sup> m<br>1 ly = 9.46 × 10<sup>15</sup> m<br>1 Parsec (pc) = 3.08 × 10<sup>16</sup> m = 3.26 ly</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• SI Supplementary Units:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">Plane Angle: dθ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ds</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> (radian, rad)<br>Solid Angle: dΩ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> (steradian, sr)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Error Formulas:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">Relative Error = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δa<sub>mean</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">a<sub>mean</sub></span>\n  </span><br>Percentage Error = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δa<sub>mean</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">a<sub>mean</sub></span>\n  </span> × 100%<br>Power Error (Z = A<sup>p</sup>): <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔZ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Z</span>\n  </span> = p <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Unit Conversion Rule:</b>\n        <span style=\"color: #FFFFFF; white-space: nowrap; display: block; overflow-x: auto;\">n<sub>2</sub> = n<sub>1</sub> × [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">M<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M<sub>2</sub></span>\n  </span> ]<sup>a</sup> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L<sub>2</sub></span>\n  </span> ]<sup>b</sup> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sub>2</sub></span>\n  </span> ]<sup>c</sup></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Principle of Homogeneity:</b>\n        <span style=\"color: #FFFFFF; display: block;\">For A + B = C, dimensions [A] = [B] = [C] must be strictly identical.</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy1HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  \n  <div style=\"text-align: center; margin-bottom: 25px; border-bottom: 2px solid #FF512F; padding-bottom: 10px;\">\n    <h2 style=\"color: #FF512F; margin: 0; font-size: 22px; font-weight: bold; text-align: center !important;\">NCERT & Master Solutions Guide</h2>\n    <p style=\"color: #B0BEC5; margin: 5px 0 0 0; font-size: 15px; text-align: center !important;\">Unit I: Physical World and Measurement (Units and Measurements) — 100 Practice Questions (Theoretical & Numerical)</p>\n  </div>\n<h3 style=\"color: #FF512F; border-left: 4px solid #FF512F; padding-left: 10px; margin-top: 25px;\">Part A: Multiple Choice Questions (Q1 - Q25)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q1: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which of the following is NOT a fundamental base SI unit?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) kelvin</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) candela</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) newton</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) mole</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) newton</span></b><br>Newton is a derived unit of Force (1 N = 1 kg m s<sup>-2</sup>), whereas kelvin, candela, and mole are SI fundamental base units.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q2: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why is measurement essential in physical sciences?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) To describe qualitative feelings</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) To establish quantitative natural laws</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) To eliminate math from physics</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) To avoid experimentation</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) To establish quantitative natural laws</span></b><br>Measurement provides exact numerical values (Q = n × u) necessary to formulate and verify quantitative physical laws.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q3: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The relation between numerical magnitude n and unit u of a physical quantity is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) n ∝ u</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) n ∝ u<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) n ∝ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">u</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) n = u</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) n ∝ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">u</span>\n  </span></span></b><br>Since total magnitude Q = n × u is constant, numerical value n is inversely proportional to unit size u (n<sub>1</sub> u<sub>1</sub> = n<sub>2</sub> u<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q4: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The plane angle (radian) and solid angle (steradian) are classified as:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Fundamental units</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Derived units</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Supplementary dimensionless units</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Imperial units</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) Supplementary dimensionless units</span></b><br>Radian and Steradian are supplementary SI units, but plane angle (ds/r) and solid angle (dA/r<sup>2</sup>) carry no dimensions [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q5: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Light year is a unit used for measuring:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Time duration</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Astronomical distance</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Intensity of light</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Velocity of photons</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) Astronomical distance</span></b><br>Light year (1 ly = 9.46 × 10<sup>15</sup> m) measures the distance light travels in vacuum in one year.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q6: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The dimensional formula for Universal Gravitational Constant G is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) [M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) [M<sup>1</sup> L<sup>3</sup> T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) [M<sup>-2</sup> L<sup>3</sup> T<sup>-1</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) [M<sup>-1</sup> L<sup>2</sup> T<sup>-2</sup>]</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">a) [M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>]</span></b><br>From F = G <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> m<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span>, G = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F r<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> m<sub>2</sub></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L T<sup>-2</sup>] [L<sup>2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[M<sup>2</sup>]</span>\n  </span> = [M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q7: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which rule applies to leading zeros when counting significant figures?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) They are always significant</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) They are never significant</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) They are significant if after decimal</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) They depend on temperature</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) They are never significant</span></b><br>Leading zeros before the first non-zero digit merely fix decimal position and are never significant (e.g. 0.0045 has 2 sig figs).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q8: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The number of significant figures in 0.007020 is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 3</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 6</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 7</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) 4</span></b><br>Leading zeros (0.00) are non-significant. Non-zero digits (7, 0, 2) and trailing zero after decimal (0) are significant. Total = 4.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q9: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which pair of physical quantities has identical dimensions?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Work and Power</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Impulse and Linear Momentum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Force and Torque</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Stress and Strain</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) Impulse and Linear Momentum</span></b><br>Impulse = Force × Time = [M L T<sup>-1</sup>], which equals Linear Momentum = Mass × Velocity = [M L T<sup>-1</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q10: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The dimensional formula for Planck's constant h is identical to:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Linear momentum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Angular momentum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Energy</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) Angular momentum</span></b><br>Planck's constant h = E/ν = [M L<sup>2</sup> T<sup>-1</sup>], which equals Angular Momentum L = m v r = [M L<sup>2</sup> T<sup>-1</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q11: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If error in measuring radius of a sphere is 2%, the percentage error in its volume is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2%</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4%</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 6%</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 8%</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) 6%</span></b><br>Volume V = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">4</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> π r<sup>3</sup>. Percentage error <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔV</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V</span>\n  </span> × 100 = 3 × (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δr</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> × 100) = 3 × 2% = 6%.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q12: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is the SI unit of Solid Angle?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Radian</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Steradian</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Degree</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Candela</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) Steradian</span></b><br>Steradian (sr) is the supplementary SI unit for solid angle.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q13: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which of the following is a dimensionless constant?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Gravitational constant G</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Refractive index n</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Euler number e</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Planck's constant h</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) Euler number e</span></b><br>Euler number e and π are dimensionless pure number constants [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q14: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">In 1.000 g, the number of significant figures is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 2</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 3</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 4</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">d) 4</span></b><br>Trailing zeros after a decimal point are significant. 1.000 has 4 significant figures.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q15: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The dimensional formula for Surface Tension is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) [M L T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) [M L<sup>0</sup> T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) [M L<sup>-1</sup> T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) [M L<sup>2</sup> T<sup>-2</sup>]</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) [M L<sup>0</sup> T<sup>-2</sup>]</span></b><br>Surface Tension = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Force</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Length</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L T<sup>-2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[L]</span>\n  </span> = [M L<sup>0</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q16: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which measurement is most precise among the following?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 5.00 mm</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 5.00 cm</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 5.00 m</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 5.00 km</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">a) 5.00 mm</span></b><br>5.00 mm has the smallest least count (0.01 mm), giving the highest experimental precision.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q17: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">1 Astronomical Unit (AU) represents the mean distance between:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Earth and Sun</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Earth and Moon</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Sun and Moon</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Sun and Jupiter</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">a) Earth and Sun</span></b><br>1 AU = 1.496 × 10<sup>11</sup> m, the mean distance from Earth to Sun.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q18: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The dimensional formula for Coefficient of Viscosity η is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) [M L<sup>-1</sup> T<sup>-1</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) [M L T<sup>-1</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) [M L<sup>-2</sup> T<sup>-1</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) [M L<sup>-1</sup> T<sup>-2</sup>]</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">a) [M L<sup>-1</sup> T<sup>-1</sup>]</span></b><br>From Stokes' Law F = 6π η r v, η = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r v</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L T<sup>-2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[L] [L T<sup>-1</sup>]</span>\n  </span> = [M L<sup>-1</sup> T<sup>-1</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q19: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The ratio of SI unit (Newton) to CGS unit (Dyne) of Force is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 10<sup>3</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 10<sup>5</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 10<sup>7</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 10<sup>-5</sup></div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) 10<sup>5</sup></span></b><br>1 Newton (SI) = 1 kg m s<sup>-2</sup> = 1000 g × 100 cm s<sup>-2</sup> = 10<sup>5</sup> dynes.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q20: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A physical quantity P is given by P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A<sup>2</sup> B</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">C</span>\n  </span>. Errors in A, B, C are 1%, 2%, 3%. Error in P is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 4%</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 7%</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 6%</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 5%</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) 7%</span></b><br>Total percentage error = 2(1%) + 1(2%) + 1(3%) = 2% + 2% + 3% = 7%.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q21: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The dimensions of Torque are identical to:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Power</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Work</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Impulse</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">c) Work</span></b><br>Torque = Force × distance = [M L<sup>2</sup> T<sup>-2</sup>], identical to Work = [M L<sup>2</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q22: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Systematic errors can be minimized by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Taking arithmetic mean of observations</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Calibrating instruments & improving technique</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Changing observers</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Increasing least count</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">b) Calibrating instruments & improving technique</span></b><br>Systematic errors arise from known causes like instrument zero error; proper calibration minimizes them.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q23: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which of the following is NOT dimensionless?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Strain</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Angle</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Refractive index</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Universal Gravitational constant G</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">d) Universal Gravitational constant G</span></b><br>G has dimensions [M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>], whereas strain, angle, and refractive index are dimensionless.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q24: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">1 Parsec equals how many light years?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 3.26 ly</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 9.46 ly</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1.5 ly</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 10 ly</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">a) 3.26 ly</span></b><br>1 Parsec (parallax second) = 3.08 × 10<sup>16</sup> m = 3.26 light years.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q25: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Round off 4.345 to 3 significant figures:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 4.34</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4.35</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 4.30</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 4.40</div>\n  </div></div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #FF512F;\">a) 4.34</span></b><br>When dropping 5 preceded by an even digit (4), the even digit remains unchanged (4.34).\n    </div>\n  </div><h3 style=\"color: #FF512F; border-left: 4px solid #FF512F; padding-left: 10px; margin-top: 35px;\">Part B: Very Short Answer Questions (Q26 - Q55)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q26: Why Measurement is Needed</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why is measurement essential in physical sciences?</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Physics is a quantitative science based on exact observation. Qualitative descriptions (like 'hot' or 'heavy') are subjective; measurement provides precise numerical values (Q = n × u) necessary to test and establish natural physical laws.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q27: Define Physical Quantity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is meant by a physical quantity in physics?</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A physical quantity is any quantifiable property of a material or natural phenomenon that can be measured using an accepted standard unit (e.g. Mass, Length, Time, Force).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q28: Define Fundamental Base Unit</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define a fundamental base unit with one standard example.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A fundamental unit is a base reference unit defined independently of all other units (e.g. metre for length, kilogram for mass, second for time).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q29: Define Derived Unit</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a derived unit? Give two examples.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A derived unit is an SI unit expressed as a mathematical combination of base fundamental units. Examples: unit of velocity (m s<sup>-1</sup>) and unit of force (kg m s<sup>-2</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q30: Define Light Year</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define one light year and state its value in SI units.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One light year (1 ly) is the total distance traveled by light in vacuum in one Julian year. 1 ly = 9.46 × 10<sup>15</sup> metres.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q31: Define Parsec</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a parsec? State its value in light years.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One parsec (parallax second) is the distance at which an arc of length 1 AU subtends an angle of 1 arc second. 1 Parsec = 3.08 × 10<sup>16</sup> m = 3.26 light years.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q32: Define Astronomical Unit (AU)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define Astronomical Unit.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An Astronomical Unit (1 AU) is the mean distance between the center of the Earth and the center of the Sun. 1 AU = 1.496 × 10<sup>11</sup> m.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q33: Radian Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define one radian plane angle.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One radian is the plane angle subtended at the center of a circle by an arc whose length is equal to the radius of the circle (dθ = ds / r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q34: Steradian Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define one steradian solid angle.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One steradian is the solid angle subtended at the center of a sphere by a surface area equal to the square of the radius of the sphere (dΩ = dA / r<sup>2</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q35: Significant Figures Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What are significant figures in experimental measurement?</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Significant figures comprise all reliable digits known with certainty plus the first single digit that is uncertain in a measured value.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q36: Precision vs Accuracy</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Distinguish between precision and accuracy in 1 sentence.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Accuracy indicates how close a measured value is to the true value, whereas precision indicates the resolution or closeness of multiple repeated measurements.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q37: Significant Figures in 0.0050</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">How many significant figures are present in 0.0050 m?</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      There are 2 significant figures (5 and the trailing zero). Leading zeros before 5 are non-significant decimal markers.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q38: Dimensional Formula of Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensional formula of Force.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensional formula of Force F = [M<sup>1</sup> L<sup>1</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q39: Dimensional Formula of Work</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensional formula of Work and Energy.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensional formula of Work W = [M<sup>1</sup> L<sup>2</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q40: Dimensional Formula of Pressure</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensional formula of Pressure.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensional formula of Pressure = Force / Area = [M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q41: Principle of Homogeneity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the Principle of Homogeneity of Dimensions.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      It states that a physical equation is dimensionally valid if and only if the dimensions of all terms on both sides of the equation are strictly identical.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q42: Dimensionless Quantity with Unit</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Name a physical quantity that has a unit but no dimensions.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Plane angle (unit: radian) and Solid angle (unit: steradian) have SI units but are dimensionless [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q43: Dimensional Constant Example</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Give two examples of dimensional constants.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Universal Gravitational Constant G ([M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>]) and Planck's constant h ([M L<sup>2</sup> T<sup>-1</sup>]).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q44: Dimensionless Constant Example</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Give two examples of dimensionless constants.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Pure numerical digits (1, 2, 3) and mathematical constants like π and e.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q45: Absolute Error Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define absolute error in measurement.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Absolute error is the magnitude of difference between the true mean value of a physical quantity and an individual measured value: Δa = |a<sub>m</sub> - a<sub>i</sub>|.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q46: Relative Error Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define relative error.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Relative error is the ratio of mean absolute error to the mean true value of the measured physical quantity: Relative Error = Δa<sub>mean</sub> / a<sub>mean</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q47: Percentage Error Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define percentage error.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Percentage error is relative error expressed in percentage: Percentage Error = (Δa<sub>mean</sub> / a<sub>mean</sub>) × 100%.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q48: Dimensions of Impulse</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensions of Impulse.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impulse = Force × Time = [M<sup>1</sup> L<sup>1</sup> T<sup>-2</sup>] × [T] = [M<sup>1</sup> L<sup>1</sup> T<sup>-1</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q49: Dimensions of Power</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensional formula of Power.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Power = Work / Time = [M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q50: Dimensions of Frequency</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensional formula of Frequency.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Frequency = 1 / Time Period = [M<sup>0</sup> L<sup>0</sup> T<sup>-1</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q51: Dimensions of Gravitational Constant</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the dimensions of Universal Gravitational Constant G.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensions of G = [M<sup>-1</sup> L<sup>3</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q52: SI Unit of Surface Tension</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the SI unit and dimensional formula of Surface Tension.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      SI unit is N m<sup>-1</sup> (or kg s<sup>-2</sup>) and dimensional formula is [M<sup>1</sup> L<sup>0</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q53: Rule for Addition of Significant Figures</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the rule for significant figures in addition/subtraction.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The final result should retain only as many decimal places as present in the measurement with the least decimal places.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q54: Rule for Multiplication of Significant Figures</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the rule for significant figures in multiplication/division.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The final result should retain only as many significant figures as present in the original measurement with the least significant figures.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q55: Limitation of Dimensional Analysis</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State one main limitation of dimensional analysis.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      It cannot determine dimensionless proportional constants (like 2π or 1/2) or derive trigonometric/exponential relations.\n    </div>\n  </div><h3 style=\"color: #FF512F; border-left: 4px solid #FF512F; padding-left: 10px; margin-top: 35px;\">Part C: Short Answer Questions (Q56 - Q85)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q56: Characteristics of a Standard Unit</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What are the four essential characteristics that a standard unit of measurement must possess?</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>Well-Defined:</b> Definition must be clear, precise, and unambiguous.<br>2. <b>Invariable:</b> Must remain constant irrespective of temperature, pressure, or location.<br>3. <b>Easily Reproducible:</b> Must be capable of exact replication globally.<br>4. <b>Universally Accepted:</b> Internationally agreed upon by global scientific consensus.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q57: Explain CGS, FPS, and MKS Systems</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Briefly describe the CGS, FPS, and MKS unit systems.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>CGS System:</b> Metric system based on Centimetre (length), Gram (mass), and Second (time).<br>2. <b>FPS System:</b> Imperial British system based on Foot (length), Pound (mass), and Second (time).<br>3. <b>MKS System:</b> Metric system based on Metre (length), Kilogram (mass), and Second (time).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q58: Why SI System is Preferred</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State three advantages of the SI system over traditional unit systems.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>Coherent System:</b> All derived units are obtained directly by simple multiplication/division of base units without conversion factors.<br>2. <b>Rational System:</b> Assigns only one specific unit to a given physical quantity (e.g. Joule for all forms of energy).<br>3. <b>Universal Metric System:</b> Based on powers of 10, making calculations and scaling simple.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q59: Explain Systematic Errors and Remedies</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What are systematic errors? Classify their types and explain how to minimize them.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Systematic errors are unidirectional errors occurring due to known flaws.<br><b>Types:</b> (i) Instrumental errors (zero error), (ii) Personal errors (parallax), (iii) Imperfection in technique.<br><b>Remedies:</b> Calibrate instruments against standards, correct zero errors, and refine experimental technique.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q60: Explain Random Errors and Least Count Error</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What are random errors and least count errors? How are random errors minimized?</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Random Errors:</b> Irregular unpredictable variations due to random environmental changes or human reaction time.<br><b>Least Count Error:</b> Uncertainty associated with the resolution limit of the instrument.<br><b>Minimization:</b> Taking arithmetic mean of a large number of repeated measurements.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q61: Check Correctness of s = ut + 1/2 at<sup>2</sup></h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Check the dimensional correctness of equation s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup>.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      LHS dimension: [s] = [L].<br>RHS Term 1: [u t] = [L T<sup>-1</sup>] × [T] = [L].<br>RHS Term 2: [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup>] = [1] × [L T<sup>-2</sup>] × [T<sup>2</sup>] = [L].<br>Since LHS = [L] and each term on RHS = [L], by Principle of Homogeneity, the equation is dimensionally correct!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q62: Derive Time Period of Simple Pendulum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive an expression for time period T of a simple pendulum depending on length l and acceleration due to gravity g.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let T = k l<sup>a</sup> g<sup>b</sup>.<br>Substitute dimensions: [M<sup>0</sup> L<sup>0</sup> T<sup>1</sup>] = [L]<sup>a</sup> [L T<sup>-2</sup>]<sup>b</sup> = [L<sup>a+b</sup> T<sup>-2b</sup>].<br>Equating powers:<br>- Power of T: -2b = 1 ⇒ b = -<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Power of L: a + b = 0 ⇒ a = -b = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>Hence T = k l<sup>1/2</sup> g<sup>-1/2</sup> = k <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span> = 2 π <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q63: Derive Centripetal Force Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for centripetal force F acting on a body of mass m moving with velocity v in radius r.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let F = k m<sup>a</sup> v<sup>b</sup> r<sup>c</sup>.<br>Dimensions: [M L T<sup>-2</sup>] = [M]<sup>a</sup> [L T<sup>-1</sup>]<sup>b</sup> [L]<sup>c</sup> = [M<sup>a</sup> L<sup>b+c</sup> T<sup>-b</sup>].<br>Equating powers:<br>- Mass: a = 1<br>- Time: -b = -2 ⇒ b = 2<br>- Length: b + c = 1 ⇒ 2 + c = 1 ⇒ c = -1<br>Hence F = k m<sup>1</sup> v<sup>2</sup> r<sup>-1</sup> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q64: Convert 1 Newton into Dynes</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Convert 1 Newton (SI unit of Force) into Dynes (CGS unit) using dimensional analysis.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Force formula F = [M L T<sup>-2</sup>].<br>Dimensions: a = 1, b = 1, c = -2.<br>Formula: n<sub>2</sub> = n<sub>1</sub> [M<sub>1</sub>/M<sub>2</sub>]<sup>1</sup> [L<sub>1</sub>/L<sub>2</sub>]<sup>1</sup> [T<sub>1</sub>/T<sub>2</sub>]<sup>-2</sup><br>n<sub>2</sub> = 1 × [1 kg / 1 g]<sup>1</sup> [1 m / 1 cm]<sup>1</sup> [1 s / 1 s]<sup>-2</sup><br>n<sub>2</sub> = 1 × (1000) × (100) × (1) = 10<sup>5</sup>.<br><b>Hence, 1 Newton = 10<sup>5</sup> Dynes.</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q65: Convert 1 Joule into Ergs</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Convert 1 Joule (SI unit of Work) into Ergs (CGS unit) using dimensional analysis.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work formula W = [M L<sup>2</sup> T<sup>-2</sup>].<br>Dimensions: a = 1, b = 2, c = -2.<br>n<sub>2</sub> = 1 × [1 kg / 1 g]<sup>1</sup> [1 m / 1 cm]<sup>2</sup> [1 s / 1 s]<sup>-2</sup><br>n<sub>2</sub> = 1 × (1000) × (100)<sup>2</sup> × (1) = 1000 × 10000 = 10<sup>7</sup>.<br><b>Hence, 1 Joule = 10<sup>7</sup> Ergs.</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q66: Percentage Error in Density Calculation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Mass of a cube is (10.0 ± 0.1) kg and edge length is (2.00 ± 0.01) m. Calculate percentage error in density.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Density ρ = Mass / Volume = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">M</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L<sup>3</sup></span>\n  </span>.<br>Percentage error <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δρ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">ρ</span>\n  </span> × 100 = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔM</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> × 100 + 3 (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔL</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L</span>\n  </span> × 100).<br>Error in M = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">0.1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">10.0</span>\n  </span> × 100 = 1%.<br>Error in L = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">0.01</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2.00</span>\n  </span> × 100 = 0.5%.<br>Total error in density = 1% + 3(0.5%) = 1% + 1.5% = <b>2.5%</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q67: Find Dimensions of Constants a and b in Van der Waals Equation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">In Van der Waals equation (P + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span>\n  </span>) (V - b) = R T, find dimensions of constants a and b.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      By Principle of Homogeneity:<br>1. Since b is subtracted from Volume V, [b] = [V] = <b>[M<sup>0</sup> L<sup>3</sup> T<sup>0</sup>]</b>.<br>2. Since <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span>\n  </span> is added to Pressure P, [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span>\n  </span>] = [P] = [M L<sup>-1</sup> T<sup>-2</sup>].<br>[a] = [P] × [V<sup>2</sup>] = [M L<sup>-1</sup> T<sup>-2</sup>] × [L<sup>6</sup>] = <b>[M L<sup>5</sup> T<sup>-2</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q68: Find Dimensions of a, b, c, d in v = a + bt + c/(d+t)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">In velocity equation v = a + b t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">c</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">d + t</span>\n  </span>, find dimensions of a, b, c, d.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. [a] = [v] = <b>[L T<sup>-1</sup>]</b>.<br>2. [b t] = [v] ⇒ [b] = [v]/[t] = <b>[L T<sup>-2</sup>]</b>.<br>3. In denominator (d + t), d is added to time t, so [d] = [t] = <b>[T]</b>.<br>4. [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">c</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">d+t</span>\n  </span>] = [v] ⇒ [c] / [T] = [L T<sup>-1</sup>] ⇒ [c] = <b>[L]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q69: Classification of Physical Quantities by Dimensions</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain the four-way classification of physical quantities based on dimensions with two examples each.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>Dimensional Variables:</b> Have dimensions and variable values (Velocity, Force).<br>2. <b>Dimensional Constants:</b> Have dimensions and fixed values (Gravitational constant G, Planck's constant h).<br>3. <b>Dimensionless Variables:</b> Variable values but no dimensions (Angle, Strain, Relative density).<br>4. <b>Dimensionless Constants:</b> Fixed values and no dimensions (Pure numbers 1, 2, π, e).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q70: Explain Parallax Method theoretically</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain the basic principle of parallax method used for measuring astronomical distances.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Parallax is the apparent change in position of an object relative to a distant background when viewed from two different positions B apart.<br>Angle subtended at target = Parallax angle θ (in radians).<br>Distance D = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Basis B</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Parallax Angle θ</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q71: Significant Figures Rules Example</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State 4 rules for identifying significant figures with an example for each.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. Non-zero digits are significant: 423 (3 sig figs).<br>2. Zeros between non-zeros are significant: 5006 (4 sig figs).<br>3. Leading zeros are non-significant: 0.007 (1 sig fig).<br>4. Trailing zeros after decimal are significant: 8.400 (4 sig figs).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q72: Differentiate Absolute, Relative, and Percentage Error</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain Absolute Error, Relative Error, and Percentage Error with mathematical expressions.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let mean value be a<sub>m</sub>.<br>1. Absolute Error Δa<sub>i</sub> = |a<sub>m</sub> - a<sub>i</sub>|.<br>2. Relative Error = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Mean Absolute Error Δa<sub>mean</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Mean Value a<sub>m</sub></span>\n  </span>.<br>3. Percentage Error = Relative Error × 100%.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q73: Significant Figures in Arithmetic Calculations</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Calculate (2.45 × 0.12) to correct significant figures.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      2.45 has 3 sig figs, 0.12 has 2 sig figs.<br>Product = 0.294.<br>By multiplication rule, result must be rounded to 2 significant figures: <b>0.29</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q74: Dimensions of Kinetic Energy</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove dimensionally that Kinetic Energy E<sub>k</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m v<sup>2</sup> has same dimensions as Work.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Kinetic Energy [E<sub>k</sub>] = [m] × [v]<sup>2</sup> = [M] × [L T<sup>-1</sup>]<sup>2</sup> = [M L<sup>2</sup> T<sup>-2</sup>].<br>Work [W] = [Force] × [Distance] = [M L T<sup>-2</sup>] × [L] = [M L<sup>2</sup> T<sup>-2</sup>].<br>Both have identical dimensions <b>[M L<sup>2</sup> T<sup>-2</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q75: Dimensions of Frequency of Stretched String</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive frequency f of a stretched string depending on length L, tension T (force), and mass per unit length m.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let f = k L<sup>a</sup> T<sup>b</sup> m<sup>c</sup>.<br>[T<sup>-1</sup>] = [L]<sup>a</sup> [M L T<sup>-2</sup>]<sup>b</sup> [M L<sup>-1</sup>]<sup>c</sup> = [M<sup>b+c</sup> L<sup>a+b-c</sup> T<sup>-2b</sup>].<br>- Time: -2b = -1 ⇒ b = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Mass: b + c = 0 ⇒ c = -b = -<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Length: a + b - c = 0 ⇒ a + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> - (-<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span>) = 0 ⇒ a + 1 = 0 ⇒ a = -1.<br>Hence f = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">k</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√m</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2L</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√m</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q76: Check Dimensional Correctness of v<sup>2</sup> - u<sup>2</sup> = 2 a s</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Verify dimensional correctness of third equation of motion v<sup>2</sup> - u<sup>2</sup> = 2 a s.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      LHS: [v<sup>2</sup>] = [L T<sup>-1</sup>]<sup>2</sup> = [L<sup>2</sup> T<sup>-2</sup>], [u<sup>2</sup>] = [L<sup>2</sup> T<sup>-2</sup>].<br>LHS = [L<sup>2</sup> T<sup>-2</sup>].<br>RHS: [2 a s] = [1] × [L T<sup>-2</sup>] × [L] = [L<sup>2</sup> T<sup>-2</sup>].<br>LHS = RHS = [L<sup>2</sup> T<sup>-2</sup>]. Equation is dimensionally correct!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q77: Dimensions of Modulus of Elasticity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive dimensional formula for Young's Modulus Y.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Young's Modulus Y = Stress / Strain = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Force / Area</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Change in Length / Original Length</span>\n  </span>.<br>[Y] = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L T<sup>-2</sup>] / [L<sup>2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[L] / [L]</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L<sup>-1</sup> T<sup>-2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[1]</span>\n  </span> = <b>[M L<sup>-1</sup> T<sup>-2</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q78: Dimensions of Angular Momentum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find dimensions of Angular Momentum L = m v r.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      [L] = [m] × [v] × [r] = [M] × [L T<sup>-1</sup>] × [L] = <b>[M L<sup>2</sup> T<sup>-1</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q79: Dimensions of Specific Heat Capacity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive dimensional formula for Specific Heat Capacity c from Q = m c ΔT.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      c = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m ΔT</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L<sup>2</sup> T<sup>-2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[M] [K]</span>\n  </span> = <b>[M<sup>0</sup> L<sup>2</sup> T<sup>-2</sup> K<sup>-1</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q80: Dimensions of Stefan's Constant</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find dimensions of Stefan's constant σ from E = σ T<sup>4</sup> (Energy per unit area per unit time).</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      E = Energy / (Area × Time) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L<sup>2</sup> T<sup>-2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[L<sup>2</sup>] [T]</span>\n  </span> = [M T<sup>-3</sup>].<br>σ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">E</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sup>4</sup></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M T<sup>-3</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[K<sup>4</sup>]</span>\n  </span> = <b>[M T<sup>-3</sup> K<sup>-4</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q81: Dimensions of Universal Gas Constant R</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive dimensions of Universal Gas Constant R from P V = n R T.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      R = P V / (n T) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L<sup>-1</sup> T<sup>-2</sup>] [L<sup>3</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[mol] [K]</span>\n  </span> = <b>[M L<sup>2</sup> T<sup>-2</sup> K<sup>-1</sup> mol<sup>-1</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q82: Check Correctness of T = 2π √(m/k)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Verify dimensionally T = 2 π <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√k</span>\n  </span> where k is spring factor (Force per unit length).</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Spring constant k = Force / Length = [M L T<sup>-2</sup>] / [L] = [M T<sup>-2</sup>].<br>RHS: [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√k</span>\n  </span>] = [M / (M T<sup>-2</sup>)]<sup>1/2</sup> = [T<sup>2</sup>]<sup>1/2</sup> = [T].<br>LHS = [T]. Equation is dimensionally correct!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q83: Express 1 g cm<sup>-3</sup> in kg m<sup>-3</sup></h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Convert density of water 1 g cm<sup>-3</sup> into SI unit kg m<sup>-3</sup>.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1 g = 10<sup>-3</sup> kg.<br>1 cm<sup>-3</sup> = (10<sup>-2</sup> m)<sup>-3</sup> = 10<sup>6</sup> m<sup>-3</sup>.<br>Density = 1 × 10<sup>-3</sup> kg × 10<sup>6</sup> m<sup>-3</sup> = <b>1000 kg m<sup>-3</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q84: Dimensions of Solar Constant</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find dimensional formula of Solar Constant (Energy received per unit area per unit time).</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Solar Constant = Energy / (Area × Time) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[M L<sup>2</sup> T<sup>-2</sup>]</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[L<sup>2</sup>] [T]</span>\n  </span> = <b>[M<sup>1</sup> L<sup>0</sup> T<sup>-3</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q85: Combination of Fractional Errors</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If x = a<sup>3</sup> b<sup>2</sup> / √c, find expression for relative error in x.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Relative error <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δx</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">x</span>\n  </span> = 3 <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δa</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">a</span>\n  </span> + 2 <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δb</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">b</span>\n  </span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δc</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">c</span>\n  </span>.\n    </div>\n  </div><h3 style=\"color: #FF512F; border-left: 4px solid #FF512F; padding-left: 10px; margin-top: 35px;\">Part D: Long Answer Questions (Q86 - Q100)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q86: Complete Theory of SI System & Base Units</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Describe the SI system of units in detail. List all 7 base fundamental quantities with their units, symbols, and official definition bases.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The International System of Units (SI) is a coherent, rationalized decimal metric system adopted globally.<br><br><b>7 Base SI Quantities:</b><br>1. <b>Length (metre, m):</b> Defined by path traveled by light in vacuum in 1/299792458 s.<br>2. <b>Mass (kilogram, kg):</b> Defined by fixing Planck's constant h = 6.62607015 × 10<sup>-34</sup> J s.<br>3. <b>Time (second, s):</b> Defined by 9192631770 periods of radiation of Cs-133 atom.<br>4. <b>Electric Current (ampere, A):</b> Defined by elementary charge e = 1.602176634 × 10<sup>-19</sup> C.<br>5. <b>Thermodynamic Temp (kelvin, K):</b> Defined by Boltzmann constant k = 1.380649 × 10<sup>-23</sup> J K<sup>-1</sup>.<br>6. <b>Amount of Substance (mole, mol):</b> Defined by Avogadro constant N<sub>A</sub> = 6.02214076 × 10<sup>23</sup>.<br>7. <b>Luminous Intensity (candela, cd):</b> Defined by 540 × 10<sup>12</sup> Hz monochromatic source.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q87: Comprehensive Error Analysis & Error Combination Proofs</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain Systematic and Random errors. Derive mathematical expressions for error combination in (i) Addition, (ii) Multiplication, and (iii) Power raised quantity.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Systematic Errors:</b> Biased errors occurring in one direction due to instrument flaw, personal bias, or imperfect experimental technique.<br><b>Random Errors:</b> Irregular unpredictable fluctuations in environmental factors or observation.<br><br><b>Error Combination Derivations:</b><br><b>(i) Addition Z = A + B:</b><br>Z ± ΔZ = (A ± ΔA) + (B ± ΔB) = (A + B) ± (ΔA + ΔB).<br>Maximum absolute error <b>ΔZ = ΔA + ΔB</b>.<br><br><b>(ii) Multiplication Z = A × B:</b><br>Z ± ΔZ = (A ± ΔA)(B ± ΔB) = A B ± A ΔB ± B ΔA ± ΔA ΔB.<br>Divide both sides by Z = A B:<br>1 ± <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔZ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Z</span>\n  </span> = 1 ± <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔB</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">B</span>\n  </span> ± <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span>.<br>Maximum relative error <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔZ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Z</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔB</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">B</span>\n  </span></b>.<br><br><b>(iii) Power Quantity Z = A<sup>p</sup>:</b><br>Taking log: ln Z = p ln A. Differentiating: <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔZ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Z</span>\n  </span> = p <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔA</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q88: Detailed Method of Dimensional Analysis Applications</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain the three main applications of dimensional analysis with one detailed numerical example for each application.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Application 1: Checking Equation Correctness</b><br>Example: Verify v = u + a t.<br>LHS = [L T<sup>-1</sup>], RHS = [L T<sup>-1</sup>] + [L T<sup>-2</sup>][T] = [L T<sup>-1</sup>]. LHS = RHS.<br><br><b>Application 2: Deriving Relations</b><br>Example: Derive viscous force F = 6π η r v on sphere of radius r moving at velocity v in medium of viscosity η.<br>F = k η<sup>a</sup> r<sup>b</sup> v<sup>c</sup> ⇒ [M L T<sup>-2</sup>] = [M L<sup>-1</sup> T<sup>-1</sup>]<sup>a</sup> [L]<sup>b</sup> [L T<sup>-1</sup>]<sup>c</sup>.<br>a = 1, -a + b + c = 1 ⇒ b = 1, -a - c = -2 ⇒ c = 1.<br>Hence F = 6π η r v.<br><br><b>Application 3: Unit System Conversion</b><br>Convert G = 6.67 × 10<sup>-11</sup> N m<sup>2</sup> kg<sup>-2</sup> to CGS units (cm<sup>3</sup> g<sup>-1</sup> s<sup>-2</sup>).<br>G<sub>CGS</sub> = 6.67 × 10<sup>-11</sup> × (1000 g / 1 g)<sup>-1</sup> (100 cm / 1 cm)<sup>3</sup> (1 s / 1 s)<sup>-2</sup> = <b>6.67 × 10<sup>-8</sup> cm<sup>3</sup> g<sup>-1</sup> s<sup>-2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q89: Limitations and Failures of Dimensional Analysis</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Discuss in detail all the limitations and boundary conditions where dimensional analysis fails.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>Dimensionless Proportionality Constants:</b> Proportionality constants (like 1/2 in 1/2 mv<sup>2</sup> or 2π in pendulum formula) carry no dimensions and cannot be deduced theoretically.<br>2. <b>More than 3 Base Variables:</b> In mechanics, if a quantity depends on 4 or more independent variables, equating M, L, T yields only 3 linear equations, making unique solution impossible.<br>3. <b>Trigonometric, Exponential & Logarithmic Functions:</b> Functions like sin(ωt), e<sup>-kx</sup>, or log(x) are inherently dimensionless; dimensional analysis cannot handle sum/difference of such functions.<br>4. <b>Sum of Terms:</b> Formulas containing sum of terms (like s = ut + 1/2 at<sup>2</sup>) cannot be derived directly from zero.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q90: Comprehensive Method of Measuring Large Distances</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain (i) Parallax method for measuring astronomical distances, and (ii) Reflection/Echo method (SONAR/RADAR).</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>(i) Parallax Method:</b><br>To measure distance D of distant planet P from Earth observatories A and B separated by baseline b:<br>Parallax angle = θ.<br>Since b << D, arc length ≈ b.<br>Angle θ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">b</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">D</span>\n  </span> ⇒ D = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">b</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">θ</span>\n  </span> (in radians).<br><br><b>(ii) RADAR / Echo Method:</b><br>A high frequency signal is transmitted towards target distance x and reflected echo received after time t.<br>Total distance traveled by signal = 2 x = v × t.<br>Target distance <b>x = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v × t</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q91: Significant Figures & Rounding Rules Deep Dive</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State all rules for determining significant figures, rounding off rules, and arithmetic operation guidelines with illustrative examples.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>1. Significant Figures Rules:</b><br>- Non-zero digits are significant (e.g. 14.8 -> 3).<br>- Trapped zeros are significant (e.g. 4005 -> 4).<br>- Leading zeros are NOT significant (e.g. 0.0025 -> 2).<br>- Trailing zeros with decimal are significant (e.g. 5.200 -> 4).<br><br><b>2. Rounding Off Rules:</b><br>- Digit < 5: preceding digit unchanged (3.42 -> 3.4).<br>- Digit > 5: preceding digit increased by 1 (3.47 -> 3.5).<br>- Digit = 5: if preceding is even, unchanged (4.25 -> 4.2); if odd, increased by 1 (4.35 -> 4.4).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q92: Derivation of Capillary Rise Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for height h of liquid rise in a capillary tube of radius r, liquid density ρ, surface tension T, and gravity g using dimensional analysis.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Assume capillary height h = k T<sup>a</sup> r<sup>b</sup> ρ<sup>c</sup> g<sup>d</sup>.<br>Dimensions:<br>[L] = [M T<sup>-2</sup>]<sup>a</sup> [L]<sup>b</sup> [M L<sup>-3</sup>]<sup>c</sup> [L T<sup>-2</sup>]<sup>d</sup> = [M<sup>a+c</sup> L<sup>b-3c+d</sup> T<sup>-2a-2d</sup>].<br>Equating powers:<br>1. Mass: a + c = 0 ⇒ c = -a<br>2. Time: -2a - 2d = 0 ⇒ d = -a<br>3. Length: b - 3c + d = 1 ⇒ b - 3(-a) + (-a) = 1 ⇒ b + 2a = 1.<br>For surface tension driven rise, a = 1 ⇒ c = -1, d = -1, b = 1 - 2 = -1.<br>Hence h = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">k T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r ρ g</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 T cos θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r ρ g</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q93: Derivation of Velocity of Transverse Wave in String</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive the velocity v of a transverse wave in a stretched string depending on tension T and mass per unit length m.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let v = k T<sup>a</sup> m<sup>b</sup>.<br>Dimensions: [L T<sup>-1</sup>] = [M L T<sup>-2</sup>]<sup>a</sup> [M L<sup>-1</sup>]<sup>b</sup> = [M<sup>a+b</sup> L<sup>a-b</sup> T<sup>-2a</sup>].<br>- Time: -2a = -1 ⇒ a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Mass: a + b = 0 ⇒ c = -b = -<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Check Length: a - b = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> - (-<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span>) = 1 (Verified).<br>Hence <b>v = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√m</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q94: Derivation of Speed of Sound in Gas (Laplace Formula)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for speed of sound v in a gas of pressure P and density ρ using dimensional analysis.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let v = k P<sup>a</sup> ρ<sup>b</sup>.<br>Dimensions: [L T<sup>-1</sup>] = [M L<sup>-1</sup> T<sup>-2</sup>]<sup>a</sup> [M L<sup>-3</sup>]<sup>b</sup> = [M<sup>a+b</sup> L<sup>-a-3b</sup> T<sup>-2a</sup>].<br>- Time: -2a = -1 ⇒ a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Mass: a + b = 0 ⇒ b = -a = -<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span><br>- Length: -a - 3b = -<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> - 3(-<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span>) = 1 (Verified).<br>Hence <b>v = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√P</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√ρ</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√(γ P)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√ρ</span>\n  </span></b> (where γ is adiabatic index).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q95: Derivation of Rate of Flow through Capillary (Poiseuille Formula)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive volume rate of flow V/t of liquid through capillary tube of radius r under pressure gradient P/l and viscosity η.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let rate of flow Q = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">t</span>\n  </span> = k r<sup>a</sup> P<sup>b</sup> l<sup>c</sup> η<sup>d</sup>.<br>Dimensions of Q: [L<sup>3</sup> T<sup>-1</sup>].<br>[L<sup>3</sup> T<sup>-1</sup>] = [L]<sup>a</sup> [M L<sup>-1</sup> T<sup>-2</sup>]<sup>b</sup> [L]<sup>c</sup> [M L<sup>-1</sup> T<sup>-1</sup>]<sup>d</sup>.<br>Equating powers:<br>Mass: b + d = 0 ⇒ d = -b<br>Time: -2b - d = -1 ⇒ -2b - (-b) = -1 ⇒ b = 1 ⇒ d = -1.<br>Length: a - b + c - d = 3 ⇒ a - 1 + c - (-1) = 3 ⇒ a + c = 3.<br>Since P and l appear together as pressure gradient P/l, c = -1 ⇒ a = 4.<br>Hence <b>Q = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">π r<sup>4</sup> P</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">8 η l</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q96: Error Analysis in Experiment of Simple Pendulum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">In simple pendulum experiment, length l = (100 ± 0.1) cm and time for 100 oscillations t = (90 ± 1) s. Calculate percentage error in g.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Formula T = 2π √(l/g) ⇒ g = 4π<sup>2</sup> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sup>2</sup></span>\n  </span>.<br>Percentage error in g:<br><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δg</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span> × 100 = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δl</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">l</span>\n  </span> × 100) + 2 (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ΔT</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T</span>\n  </span> × 100).<br>Error in l = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">0.1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">100</span>\n  </span> × 100 = 0.1%.<br>Error in T = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">90</span>\n  </span> × 100 = 1.11%.<br>Total percentage error in g = 0.1% + 2(1.11%) = 0.1% + 2.22% = <b>2.32%</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q97: Dimensions of Electromagnetic & Thermodynamic Constants</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive dimensional formulas for: (i) Permittivity of free space ε<sub>0</sub>, (ii) Permeability of free space μ<sub>0</sub>, (iii) Boltzmann constant k.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>(i) Permittivity ε<sub>0</sub>:</b><br>From Coulomb's Law F = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>1</sub> q<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span>.<br>ε<sub>0</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">F r<sup>2</sup></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">[A T]<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[M L T<sup>-2</sup>] [L<sup>2</sup>]</span>\n  </span> = <b>[M<sup>-1</sup> L<sup>-3</sup> T<sup>4</sup> A<sup>2</sup>]</b>.<br><br><b>(ii) Permeability μ<sub>0</sub>:</b><br>From c = 1/√(μ<sub>0</sub> ε<sub>0</sub>) ⇒ μ<sub>0</sub> = 1/(c<sup>2</sup> ε<sub>0</sub>).<br>μ<sub>0</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">[L T<sup>-1</sup>]<sup>2</sup> [M<sup>-1</sup> L<sup>-3</sup> T<sup>4</sup> A<sup>2</sup>]</span>\n  </span> = <b>[M L T<sup>-2</sup> A<sup>-2</sup>]</b>.<br><br><b>(iii) Boltzmann constant k:</b><br>From E = 3/2 k T ⇒ k = E / T = <b>[M L<sup>2</sup> T<sup>-2</sup> K<sup>-1</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q98: Derivation of Terminal Velocity (Stokes' Law)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive terminal velocity v<sub>t</sub> of sphere of radius r, density ρ falling in fluid of density σ and viscosity η.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Net downward force F = Weight - Buoyancy = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">4</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> π r<sup>3</sup> (ρ - σ) g.<br>Viscous drag force F<sub>v</sub> = 6 π η r v<sub>t</sub>.<br>At terminal velocity F = F<sub>v</sub>:<br>6 π η r v<sub>t</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">4</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> π r<sup>3</sup> (ρ - σ) g.<br><b>v<sub>t</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 r<sup>2</sup> (ρ - σ) g</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">9 η</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q99: Dimensional Correctness of Relativistic Mass</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Check dimensional correctness of Einstein's mass variation formula m = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>0</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√(1 - v<sup>2</sup>/c<sup>2</sup>)</span>\n  </span>.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      LHS = [m] = [M].<br>RHS Numerator = [m<sub>0</sub>] = [M].<br>RHS Denominator: v<sup>2</sup>/c<sup>2</sup> = [L T<sup>-1</sup>]<sup>2</sup> / [L T<sup>-1</sup>]<sup>2</sup> = [1] (Dimensionless).<br>Hence 1 - v<sup>2</sup>/c<sup>2</sup> is dimensionless [1].<br>RHS = [M] / [1] = [M].<br>LHS = RHS = [M]. Equation is dimensionally valid!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q100: Master Numerical Problem on Error Propagation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A physical quantity X is calculated using X = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a<sup>2</sup> b<sup>3</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">c √d</span>\n  </span>. If percentage errors in a, b, c, d are 2%, 1%, 3%, 4% respectively, calculate maximum percentage error in X.</div>\n    <div style=\"background: rgba(255, 81, 47, 0.05); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Fractional error expression:<br><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δx</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">x</span>\n  </span> = 2 <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δa</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">a</span>\n  </span> + 3 <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δb</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">b</span>\n  </span> + 1 <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δc</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">c</span>\n  </span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Δd</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">d</span>\n  </span>.<br><br>Substitute percentage errors:<br>Percentage error in X = 2(2%) + 3(1%) + 1(3%) + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span>(4%)<br>= 4% + 3% + 3% + 2% = <b>12%</b>.\n    </div>\n  </div></div>";
